static const int32 GM1LevelLightTableCount = UE_ARRAY_COUNT(GM1LevelLightTable);

static TArrayView<const FM1Light> M1LightsForLevel(const FString& MapName)
{
	for (const FM1LevelLights& Level : GM1LevelLightTable)
	{
		if (MapName.Contains(Level.LevelName, ESearchCase::IgnoreCase))
		{
			return TArrayView<const FM1Light>(Level.Lights, Level.Count);
		}
	}
	return TArrayView<const FM1Light>();
}
